searchUrl:
@js:
var option = {   
        "method": "POST",
        "body": "app=midu&keyword={{key}}&page={{page-1}}"
    };
try{
"https://api.midureader.com/fiction/search/search,"+ JSON.stringify(option)
}
catch(e){
	"https://api.midureader.com/fiction/search/searchV2,"+ JSON.stringify(option)
	}

contentRule.nextContentUrl:
@js:
text = java.getString("#linkNext@text")
java.log(baseUrl)
if (text == "下一页") {
  next = src.match(/(eval.+)\n/)[1]
  eval(String(next))
  __nextPage
}

