        'var text="";if(item.repliedUserNickname)text+=" 回复 "+item.repliedUserNickname;text+="："+String(item.text||"");',
        'row.appendChild(document.createTextNode(text));return row;',
        '}',
        'window.sqLoadReplies=function(button){',
        'if(!button||button.disabled)return;var cfg=window.sqReplyRequest||{};var box=document.getElementById(button.getAttribute("data-target"));if(!box)return;',
        'button.disabled=true;button.textContent="加载中...";',
        'try{',
        'var body={apiKey:cfg.apiKey,bookId:String(cfg.bookId||""),chapterId:String(cfg.chapterId||""),mid:String(button.getAttribute("data-mid")||""),itemIndex:Number(button.getAttribute("data-cursor")||0),size:20,authorId:String(button.getAttribute("data-author")||"0")};',
        'var option={method:"POST",body:JSON.stringify(body),headers:{"Content-Type":"application/json","Accept":"application/json"}};',
        'var raw=window.java.ajax(cfg.apiBase+"/v1/comments/chapter-replies,"+JSON.stringify(option));var response=JSON.parse(String(raw||"{}").replace(/^\\uFEFF/,""));',
        'if(!response.ok)throw new Error(response.error||"回复加载失败");var outer=response.data||{},data=outer.data||{},list=data.commentList||[];',
        'for(var i=0;i<list.length;i++)box.appendChild(replyNode(list[i]));',
        'var next=data.nextItemIndex;if(next===null||next===undefined)next=response.pagination&&response.pagination.nextItemIndex;',
