    var html='<html><body><div id="qd-decoded" data-version="8.2" data-mode="decoded" data-jobs="'+state.jobs.length+'" data-changed="'+changed+'">';
    for(var p=0;p<state.paragraphs.length;p++) {
      var line='';
      for(var t=0;t<state.paragraphs[p].length;t++) {
